custom_scss:
// XGC Brand Colors - Light Theme
$primary: #2E7D32;
$primary-light: #81C784;
$primary-dark: #1B5E20;
$accent: #4CAF50;

// Typography
$font-family-sans-serif: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
$font-size-base: 1rem;

// Light surface colors
$bg-color: #FFFFFF;
$text-color: #1e293b;
$border-color: #e2e8f0;

// XGC Brand Colors - Dark Theme
$primary: #66BB6A;
$primary-light: #A5D6A7;
$primary-dark: #388E3C;
$accent: #4CAF50;

// Typography
$font-family-sans-serif: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
$font-size-base: 1rem;

// Dark surface colors
$bg-color: #0f172a;
$surface-color: #1e293b;
$text-color: #e2e8f0;
$border-color: #334155;
